package com.leetcode.backend.model;
import jakarta.persistence.*; import java.util.*;
@Entity @Table(name="problem_lists",uniqueConstraints=@UniqueConstraint(columnNames={"user_id","name"})) public class ProblemList { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="user_id") private User user; @Column(nullable=false) private String name; @OneToMany(mappedBy="list",cascade=CascadeType.ALL,orphanRemoval=true) @OrderBy("position") private List<ProblemListItem> items=new ArrayList<>(); public Long getId(){return id;} public User getUser(){return user;} public void setUser(User v){user=v;} public String getName(){return name;} public void setName(String v){name=v;} public List<ProblemListItem> getItems(){return items;} }
